class Sorter {
  int[] a;
  Sorter(int[] x) {
    a = x;
  }
  void sort() {
    for (int i = 0; i < a.length - 1; i++) {
      int small = i;
      for (int j = i + 1; j < a.length; j++) {
        if (a[j] < a[small]) small = j;
      }
      int t = a[i];
      a[i] = a[small];
      a[small] = t;
    }
  }
  void show() {
    for (int i = 0; i < a.length; i++) System.out.print(a[i] + " ");
  }
  public static void main(String[] args) {
    int[] x = {11, 8, 2, 15, 6, 4};
    Sorter s = new Sorter(x);
    s.sort();
    s.show();
  }
}
```

