class Transpose {
  int[][] m;
  Transpose(int[][] x) {
    m = x;
  }
  int[][] flip() {
    int[][] t = new int[m[0].length][m.length];
    for (int i = 0; i < m.length; i++) {
      for (int j = 0; j < m[0].length; j++) {
        t[j][i] = m[i][j];
      }
    }
    return t;
  }
  public static void main(String[] args) {
    int[][] x = {{9, 3}, {2, 8}};
    Transpose o = new Transpose(x);
    int[][] t = o.flip();
    System.out.println(t[0][1]);
  }
}
